async function installKit(id,bankIndex,undo=true){const owner=state,task=++kitTask,sounds=await getKit(id);if(owner!==state||task!==kitTask)throw Error('Chargement annulé.');const indices=new Set(Array.from({length:16},(_,i)=>bankIndex*16+i));const total=state.pads.reduce((n,p,i)=>n+(indices.has(i)?0:p.data.length+(p.right?.length||0)),0)+sounds.reduce((n,p)=>n+p.data.length,0);if(total>RATE*240)throw Error('La mémoire est pleine. Exporte ton projet et libère quelques sons.');if(undo)remember();for(let i=0;i<16;i++){const target=bankIndex*16+i,s=sounds[i];audio.stop(target);state.pads[target]={...M.blank(),name:PocketStarter.names[i].replace('Eb','E♭').replace('Bb','B♭'),data:s.data.slice(),choke:s.kind==='hat'?bankIndex+1:0}}state.bank=bankIndex;state.selected=bankIndex*16;state.kit=PocketStarter.kits.find(k=>k.id===id).name;render();if(undo)changed()}
function demoDestination(){return state.patterns[state.pattern].notes.length===0?state.pattern:state.patterns.findIndex(p=>!p.notes.length)}
function renderKitOptions(){const k=PocketStarter.kits.find(k=>k.id===chosenKit),destination=demoDestination();$('#kitDemo').disabled=destination<0;if(destination<0)$('#kitDemo').checked=false;$('#kitTempoLabel').hidden=!$('#kitDemo').checked;$('#kitBPM').textContent=k.bpm+' BPM';$('#kitDemoInfo').textContent=destination<0?'Toutes les boucles sont occupées : le kit peut être chargé sans démo.':$('#kitDemo').checked?'Démo → Boucle '+(destination+1)+' · 2 mesures · aucune boucle occupée ne sera remplacée.':'Optionnel : un rythme de 2 mesures pour essayer les sons ensemble.';$('#loadKit').textContent=$('#kitDemo').checked?'Charger le kit + sa démo':'Remplacer les 16 pads de '+'ABCD'[kitTarget];const host=$('#kitSounds');host.replaceChildren();for(let i=0;i<16;i++){const b=document.createElement('button');b.textContent=PocketStarter.names[i].replace('Eb','E♭').replace('Bb','B♭');b.setAttribute('aria-label','Écouter '+k.name+' '+b.textContent);b.onclick=()=>previewKitSound(chosenKit,i).catch(e=>message(e.message));host.append(b)}}
$('#kitDemo').onchange=renderKitOptions;
async function previewKitSound(id,index){stopPreview();const epoch=previewEpoch;await unlock();const sounds=await getKit(id);if(epoch!==previewEpoch||!$('#kitSheet').open)return;const data=sounds[index].data,buffer=audio.ctx.createBuffer(1,data.length,RATE);buffer.copyToChannel(data,0);const src=audio.ctx.createBufferSource(),g=audio.ctx.createGain();src.buffer=buffer;g.gain.value=.8*.78;src.connect(g).connect(audio.ctx.destination);preview=src;previewGain=g;src.onended=()=>{src.disconnect();g.disconnect();if(preview===src){preview=null;previewGain=null}};src.start()}
$('#loadKit').onclick=async()=>{const b=$('#loadKit'),id=chosenKit,bank=kitTarget,owner=state,withDemo=$('#kitDemo').checked,withTempo=$('#kitDemoTempo').checked,destination=demoDestination();if(withDemo&&destination<0){message('Choisis une boucle vide pour la démo.');return}b.disabled=true;const buttons=$$('#kitCards button');buttons.forEach(b=>b.disabled=true);$('#kitDemo').disabled=true;try{stop();stopPreview();await installKit(id,bank);if(owner!==state)throw Error('Le projet a changé.');if(withDemo){const target=state.patterns[destination].notes.length===0?destination:demoDestination();if(target<0)throw Error('Kit chargé ; aucune boucle vide ne reste pour la démo.');const demo=PocketStarter.demo(id,bank*16);state.patterns[target]={name:demo.name,bars:demo.bars,notes:demo.notes.map(n=>({...n}))};state.pattern=target;page=0;if(withTempo){state.bpm=demo.bpm;$('#tempoInput').value=demo.bpm;if(audio.ctx)audio.delay.delayTime.setTargetAtTime(60/demo.bpm/2,audio.ctx.currentTime,.03)}changed();render()}clearTimeout(saveTimer);const ok=await save();$('#kitSheet').close();message(ok?(withDemo?'Kit et démo chargés · touche Jouer la boucle.':'Nouveaux sons chargés et gardés sur cet appareil.'):'Kit chargé. Exporte le projet pour le conserver.')}catch(e){message(e.message)}finally{b.disabled=false;buttons.forEach(b=>b.disabled=false);renderKitOptions()}};
function showEditor(){if(state.pads[state.selected].data.length<2){showSource(state.selected);return}editorTab='cut';setScreen('edit');renderEditor();requestAnimationFrame(drawWave)}$('#editSound').onclick=showEditor;$('#editDone').onclick=()=>setScreen('play');
$$('[data-editor]').forEach(b=>b.onclick=()=>{editorTab=b.dataset.editor;renderEditor();if(editorTab==='cut')requestAnimationFrame(drawWave)});
function renderEditor(){const p=state.pads[state.selected];$('#editPadLabel').textContent='SON '+label(state.selected);$('#editName').textContent=p.name;$$('[data-editor]').forEach(b=>b.classList.toggle('active',b.dataset.editor===editorTab));$$('.edit-page').forEach(el=>el.hidden=el.id!=='editor-'+editorTab);$('#trimStart').value=(p.start*p.data.length/RATE).toFixed(3);$('#trimEnd').value=(p.end*p.data.length/RATE).toFixed(3);$('#volume').value=p.volume*100;$('#volumeValue').textContent=Math.round(p.volume*100)+' %';$('#pitch').value=p.pitch;$('#pitchValue').textContent=(p.pitch>0?'+':'')+p.pitch+' demi-tons';$('#pan').value=p.pan*100;$('#panValue').textContent=p.pan===0?'Centre':p.pan<0?'Gauche':'Droite';$('#attack').value=p.attack;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===p.mode));$('#mute').textContent=p.muted?'Réactiver le son':'Rendre muet';$('#solo').textContent=p.solo?'Quitter l’écoute seule':'Écouter seul';if(editorTab==='cut')requestAnimationFrame(drawWave)}
function drawWave(){const cv=$('#wave'),r=cv.getBoundingClientRect();if(!r.width||screen!=='edit')return;const dpr=Math.min(2,window.devicePixelRatio||1);cv.width=r.width*dpr;cv.height=r.height*dpr;const g=cv.getContext('2d');g.scale(dpr,dpr);const w=r.width,h=r.height,p=state.pads[state.selected],data=p.data;g.fillStyle='#111a20';g.fillRect(0,0,w,h);g.fillStyle='#d5f67b15';g.fillRect(p.start*w,0,(p.end-p.start)*w,h);g.strokeStyle='#adcac0';g.lineWidth=1;g.beginPath();for(let x=0;x<w;x++){const a=Math.floor(x*data.length/w),b=Math.floor((x+1)*data.length/w),stride=Math.max(1,Math.floor((b-a)/24));let lo=0,hi=0;for(let j=a;j<b;j+=stride){lo=Math.min(lo,data[j]);hi=Math.max(hi,data[j])}g.moveTo(x,h/2+lo*h*.4);g.lineTo(x,h/2+hi*h*.4)}g.stroke();for(const [value,isEnd]of [[p.start,false],[p.end,true]]){const x=Math.min(w-4,Math.max(0,value*w));g.fillStyle='#d5f67b';g.fillRect(x,0,3,h);g.beginPath();g.roundRect(Math.min(w-18,Math.max(0,x-(isEnd?15:0))),isEnd?h-28:0,18,28,4);g.fill()}}
$('#wave').onpointerdown=e=>{e.preventDefault();const cv=e.currentTarget,r=cv.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,p=state.pads[state.selected];remember();waveDrag={token:e.pointerId,owner:p,edge:Math.abs(x-p.start)<Math.abs(x-p.end)?'start':'end'};cv.setPointerCapture(e.pointerId);moveWave(e)};
function moveWave(e){if(!waveDrag||waveDrag.token!==e.pointerId||state.pads[state.selected]!==waveDrag.owner)return;const p=waveDrag.owner,r=$('#wave').getBoundingClientRect(),x=M.bound((e.clientX-r.left)/r.width,0,1,0),min=Math.min(.01,1/p.data.length);if(waveDrag.edge==='start')p.start=Math.min(p.end-min,x);else p.end=Math.max(p.start+min,x);$('#trimStart').value=(p.start*p.data.length/RATE).toFixed(3);$('#trimEnd').value=(p.end*p.data.length/RATE).toFixed(3);drawWave()}
$('#wave').onpointermove=moveWave;for(const type of ['pointerup','pointercancel','lostpointercapture'])$('#wave').addEventListener(type,()=>{if(waveDrag){waveDrag=null;changed();renderSelection()}});
for(const [id,key]of [['trimStart','start'],['trimEnd','end']])$('#'+id).onchange=()=>{remember();const p=state.pads[state.selected],value=+$('#'+id).value*RATE/p.data.length;if(key==='start')p.start=M.bound(value,0,p.end-1/p.data.length,0);else p.end=M.bound(value,p.start+1/p.data.length,1,1);changed();renderEditor();renderSelection()};
$('#audition').onclick=async()=>{try{await unlock();audio.stop(state.selected);audio.play({...state.pads[state.selected],mode:'one'},state.selected,{force:true});}catch(e){message(e.message)}};
for(const [id,key,scale]of [['volume','volume',100],['pitch','pitch',1],['pan','pan',100],['attack','attack',1]]){const input=$('#'+id);input.onpointerdown=remember;input.onkeydown=e=>{if(e.key.startsWith('Arrow'))remember()};input.oninput=()=>{state.pads[state.selected][key]=+input.value/scale;changed();renderEditor()}}
$$('[data-mode]').forEach(b=>b.onclick=()=>{remember();audio.stop(state.selected);state.pads[state.selected].mode=b.dataset.mode;changed();renderEditor();renderSelection()});
$('#normalize').onclick=()=>{remember();const p=state.pads[state.selected],from=Math.floor(p.start*p.data.length),to=Math.ceil(p.end*p.data.length);let peak=0;for(const data of [p.data,p.right])if(data)for(let i=from;i<to;i++)peak=Math.max(peak,Math.abs(data[i]));if(peak){for(const key of ['data','right'])if(p[key]){const copy=p[key].slice();for(let i=from;i<to;i++)copy[i]*=.9/peak;p[key]=copy}}changed();render();message('Le volume de la sélection a été équilibré.')};
$('#reverse').onclick=()=>{remember();audio.stop(state.selected);const p=state.pads[state.selected],from=Math.floor(p.start*p.data.length),to=Math.ceil(p.end*p.data.length);for(const key of ['data','right'])if(p[key]){const copy=p[key].slice();copy.set(copy.slice(from,to).reverse(),from);p[key]=copy}changed();render();message('La sélection se lit maintenant dans l’autre sens.')};
$('#slice').onclick=()=>{const p=state.pads[state.selected],count=+$('#sliceCount').value,empty=state.pads.map((p,i)=>p.data.length<2?i:-1).filter(i=>i>=0);if(empty.length<count){message('Il faut '+count+' pads vides pour garder toutes les tranches.');return}const from=Math.floor(p.start*p.data.length),to=Math.floor(p.end*p.data.length),frames=to-from;if(frames<count){message('Cet extrait est trop court.');return}const add=frames*(p.right?2:1),total=state.pads.reduce((n,p)=>n+p.data.length+(p.right?.length||0),0);if(total+add>RATE*240){message('Pas assez de mémoire pour dupliquer ces tranches.');return}remember();for(let i=0;i<count;i++){const a=from+Math.floor(frames*i/count),b=from+Math.floor(frames*(i+1)/count);state.pads[empty[i]]={...M.blank(),name:p.name+' '+(i+1),data:p.data.slice(a,b),right:p.right?.slice(a,b)||null,volume:p.volume}}state.selected=empty[0];state.bank=Math.floor(empty[0]/16);changed();setScreen('play');render();message(count+' tranches prêtes. Ton original est conservé.')};
$('#mute').onclick=()=>{remember();const p=state.pads[state.selected];p.muted=!p.muted;if(p.muted)audio.stop(state.selected);changed();render()};$('#solo').onclick=()=>{remember();const p=state.pads[state.selected],on=!p.solo;for(const q of state.pads)q.solo=false;p.solo=on;if(on)for(const v of [...audio.voices])if(v.index!==state.selected)audio.release(v);changed();render()};$('#stopPad').onclick=()=>{audio.stop(state.selected);message('Ce son est arrêté. Les autres continuent.')};
$('#copyPad').onclick=()=>{const i=state.pads.findIndex(p=>p.data.length<2);if(i<0){message('Il n’y a plus de pad vide.');return}const p=state.pads[state.selected];try{audioMemory(i,p.data,p.right);remember();state.pads[i]={...p,name:p.name+' copie',data:p.data.slice(),right:p.right?.slice()||null};changed();render();message('Copie sur '+label(i)+'.')}catch(e){message(e.message)}};
$('#deletePad').onclick=()=>{remember();audio.stop(state.selected);const i=state.selected;state.pads[i]=M.blank();for(const p of state.patterns)p.notes=p.notes.filter(n=>n.pad!==i);changed();setScreen('play');render();message('Son effacé. Annuler le récupère.')};
$('#keyboardOpen').onclick=()=>{if(state.pads[state.selected].data.length<2){message('Choisis un son pour jouer en notes.');return}$('#keyTitle').textContent=state.pads[state.selected].name+' en notes.';open('keyboard')};
for(const [i,pitch]of [0,2,3,5,7,8,10,12].entries()){const b=document.createElement('button');b.textContent=['Do','Ré','Mi♭','Fa','Sol','La♭','Si♭','Do'][i];b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('hit');hit(state.selected,'key:'+e.pointerId,pitch+octave*12)};const off=e=>{b.classList.remove('hit');release('key:'+e.pointerId)};b.onpointerup=off;b.onpointercancel=off;b.onlostpointercapture=off;b.onclick=e=>{if(e.detail===0)hit(state.selected,null,pitch+octave*12)};$('#keys').append(b)}for(const [id,delta]of [['octDown',-1],['octUp',1]])$('#'+id).onclick=()=>{octave=M.bound(octave+delta,-1,1,0);$('#octLabel').textContent='Octave '+(octave>0?'+':'')+octave};
function paintFX(){const f=audio.fx;$('#xyCursor').style.left=(15+(f.filter+1)/2*70)+'%';$('#xyCursor').style.top=(85-f.space*70)+'%';$('#fxEcho').value=f.echo*100;$('#fxDrive').value=f.drive*100;$('#xy').setAttribute('aria-valuenow',Math.round(f.space*100))}
let xyToken=null;function moveXY(e){if(xyToken!==e.pointerId)return;const r=$('#xy').getBoundingClientRect(),x=M.bound((e.clientX-r.left)/r.width,0,1,.5),y=M.bound((e.clientY-r.top)/r.height,0,1,1);audio.apply({filter:x*2-1,space:1-y});paintFX()}
$('#xy').onpointerdown=async e=>{if(xyToken!==null)return;e.preventDefault();xyToken=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);try{if(!audio.ctx||audio.ctx.state!=='running')await unlock();if(xyToken===e.pointerId)moveXY(e)}catch(err){message(err.message)}};$('#xy').onpointermove=moveXY;function releaseXY(e){if(xyToken!==e.pointerId)return;xyToken=null;if(!fxHeld){audio.apply({filter:0,space:0});paintFX()}}for(const type of ['pointerup','pointercancel','lostpointercapture'])$('#xy').addEventListener(type,releaseXY);$('#xy').onkeydown=async e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();await unlock();audio.apply(e.key==='ArrowLeft'?{filter:Math.max(-1,audio.fx.filter-.1)}:e.key==='ArrowRight'?{filter:Math.min(1,audio.fx.filter+.1)}:e.key==='ArrowUp'?{space:Math.min(1,audio.fx.space+.1)}:{space:Math.max(0,audio.fx.space-.1)});paintFX()};
for(const [id,key]of [['fxEcho','echo'],['fxDrive','drive']])$('#'+id).oninput=async()=>{try{await unlock();audio.apply({[key]:+$('#'+id).value/100})}catch(e){message(e.message)}};
$('#fxHold').onclick=()=>{fxHeld=!fxHeld;$('#fxHold').classList.toggle('active',fxHeld);$('#fxHold').setAttribute('aria-pressed',fxHeld);$('#fxHold').textContent=fxHeld?'● Geste gardé':'○ Garder le geste';if(!fxHeld){audio.apply({filter:0,space:0});paintFX()}};$('#fxReset').onclick=()=>{audio.apply({filter:0,space:0,echo:0,drive:0});paintFX();message('Tous les effets sont relâchés.')};
function openProjects(){$('#nameInput').value=state.name;$('#captureAudio').textContent=capture?'■ Terminer et garder la performance':'Enregistrer la performance';open('projectSheet')}$('#projectOpen').onclick=openProjects;$('#menuOpen').onclick=openProjects;$('#helpOpen').onclick=()=>{$('#projectSheet').close();open('helpSheet')};$('#nameInput').onchange=()=>{remember();state.name=$('#nameInput').value.trim()||'Mon idée';changed();render()};
