function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function safeName(name){return (name||'Pocket Studio').replace(/[^\p{L}\p{N}_ -]/gu,'').slice(0,45)||'Pocket Studio'}
$('#saveProject').onclick=async()=>{try{message('Ta copie se prépare…');await new Promise(r=>requestAnimationFrame(r));const saved=M.clone(state);saved.pads=saved.pads.map(p=>({...p,data:base64(p.data),right:p.right?base64(p.right):null}));download(new Blob([JSON.stringify(saved)],{type:'application/json'}),safeName(state.name)+'.pocket.json');message('Copie exportée avec tous tes sons et tes boucles.')}catch(e){message(e.message)}};
$('#openProject').onclick=()=>$('#projectFile').click();$('#projectFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>64*1024*1024)throw Error('Ce projet dépasse 64 Mo.');const o=JSON.parse(await file.text()),legacy=o.format==='pocket-sample',incoming=legacy?M.legacy(o,unpack):M.validate(o,unpack);remember();stop();finishMic();stopPreview();state=incoming;kitTask++;audio.buffers=new WeakMap();for(const d of $$('dialog'))d.close();render();changed();await save();message(legacy?'Ancien projet importé : 64 pads, 8 boucles, 4 mesures maximum. Effets avancés et tranches par note non repris.':'Ton projet est prêt à jouer.')}catch(err){message(err.message)}};
$('#newProject').onclick=()=>{if(!window.confirm('Créer une idée vide ? Le projet actuel pourra être récupéré avec Annuler. Pense à exporter une copie.'))return;remember();stop();finishMic();stopPreview();state=M.fresh();state.kit='Mes sons';kitTask++;$('#projectSheet').close();render();changed();message('Un terrain vide. Ajoute ton premier son avec +.')};
function wav(buffer){const channels=buffer.numberOfChannels,frames=buffer.length,bytes=new ArrayBuffer(44+frames*channels*2),v=new DataView(bytes),word=(at,t)=>{for(let i=0;i<t.length;i++)v.setUint8(at+i,t.charCodeAt(i))};word(0,'RIFF');v.setUint32(4,36+frames*channels*2,true);word(8,'WAVE');word(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*channels*2,true);v.setUint16(32,channels*2,true);v.setUint16(34,16,true);word(36,'data');v.setUint32(40,frames*channels*2,true);const data=Array.from({length:channels},(_,i)=>buffer.getChannelData(i));let at=44;for(let i=0;i<frames;i++)for(let ch=0;ch<channels;ch++){const x=Math.min(1,Math.max(-1,data[ch][i]));v.setInt16(at,x<0?x*32768:x*32767,true);at+=2}return new Blob([bytes],{type:'audio/wav'})}
async function renderLoop(){const pattern=state.patterns[state.pattern];if(!pattern.notes.length)throw Error('Cette boucle est vide. Joue avec REC ou place quelques sons.');const dt=60/state.bpm/4,len=pattern.bars*16*dt,c=new OfflineAudioContext(2,Math.ceil((len+2.5)*RATE),RATE),bus=c.createGain(),hp=c.createBiquadFilter(),lp=c.createBiquadFilter(),drive=c.createWaveShaper(),master=c.createGain(),limit=c.createDynamicsCompressor(),f={...audio.fx};hp.type='highpass';hp.frequency.value=f.filter>0?20*2**(f.filter*9):20;lp.type='lowpass';lp.frequency.value=f.filter<0?Math.max(180,20000*2**(f.filter*7)):20000;if(f.drive){const curve=new Float32Array(2048),k=1+f.drive*14;for(let i=0;i<curve.length;i++)curve[i]=Math.tanh((i/(curve.length-1)*2-1)*k)/Math.tanh(k);drive.curve=curve}master.gain.value=.78;limit.threshold.value=-3;limit.knee.value=4;limit.ratio.value=12;limit.attack.value=.003;limit.release.value=.15;if(typeof PocketLoFi!=='undefined')await PocketLoFi.prepare(c);const renderRack=typeof createStudioRack==='function'?createStudioRack(c,bus,hp,state.masterFX):null;if(!renderRack)bus.connect(hp);hp.connect(lp).connect(drive).connect(master).connect(limit).connect(c.destination);if(f.echo){const delay=c.createDelay(2),feedback=c.createGain(),wet=c.createGain();delay.delayTime.value=60/state.bpm/2;feedback.gain.value=.3;wet.gain.value=f.echo*.55;drive.connect(delay);delay.connect(feedback).connect(delay);delay.connect(wet).connect(master)}if(f.space){await unlock();const verb=c.createConvolver(),wet=c.createGain();verb.buffer=audio.verb.buffer;wet.gain.value=f.space*.7;drive.connect(verb).connect(wet).connect(master)}for(const n of pattern.notes)if(eligible(n.pad)){const p=state.pads[n.pad],time=n.step*dt+(Math.floor(n.step)%2?dt*(+$('#swing').value/100):0);audio.play(p,n.pad,{time,context:c,destination:bus,pitch:n.pitch,velocity:n.velocity,gate:!!n.gated,duration:n.gated||p.mode==='hold'?n.duration*dt:p.mode==='loop'?len-time:null})}return c.startRendering()}
$('#exportAudio').onclick=async()=>{const b=$('#exportAudio');b.disabled=true;try{message('La boucle et ses effets se préparent…');const result=await renderLoop();download(wav(result),safeName(state.name)+'-boucle.wav');message('Boucle exportée en WAV stéréo, effets et fins de sons inclus.')}catch(e){message(e.message)}finally{b.disabled=false}};
function finishCapture(){if(capture?.recorder.state==='recording')capture.recorder.stop()}
$('#captureAudio').onclick=async()=>{if(capture){finishCapture();return}try{await unlock();if(!window.MediaRecorder||!audio.ctx.createMediaStreamDestination)throw Error('Enregistrement du mix indisponible dans ce navigateur.');const output=audio.ctx.createMediaStreamDestination();audio.output.connect(output);const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t)),recorder=new MediaRecorder(output.stream,mime?{mimeType:mime}:{}),session={recorder,output,chunks:[]};capture=session;recorder.ondataavailable=e=>{if(e.data.size)session.chunks.push(e.data)};recorder.onstop=()=>{clearTimeout(session.limit);audio.output.disconnect(output);output.stream.getTracks().forEach(t=>t.stop());capture=null;download(new Blob(session.chunks,{type:recorder.mimeType}),safeName(state.name)+'-performance.'+(recorder.mimeType.includes('mp4')?'m4a':'webm'));$('#captureAudio').textContent='Enregistrer la performance';message('Performance gardée. Audio compressé, durée maximale 2 minutes.')};recorder.start();session.limit=setTimeout(finishCapture,120000);$('#projectSheet').close();message('Performance enregistrée · menu Projet pour terminer. Maximum 2 minutes.')}catch(e){message(e.message)}};
let taps=[];$('#tempoOpen').onclick=()=>{$('#tempoInput').value=Math.round(state.bpm);open('tempoSheet')};$('#tapTempo').onclick=()=>{const now=Date.now();if(now-(taps.at(-1)||0)>2000)taps=[];taps.push(now);if(taps.length>5)taps.shift();if(taps.length>1)$('#tempoInput').value=Math.round(60000*(taps.length-1)/(now-taps[0]));message('Tape régulièrement le tempo qui te plaît.')};$('#tempoDone').onclick=()=>{remember();state.bpm=M.bound(+$('#tempoInput').value,40,220,112);if(audio.ctx)audio.delay.delayTime.setTargetAtTime(60/state.bpm/2,audio.ctx.currentTime,.03);render();changed();$('#tempoSheet').close()};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();stopPreview();finishMic();finishCapture();audio.apply({filter:0,space:0,echo:0,drive:0});paintFX();if(dirty)save();audio.ctx?.suspend()} });window.addEventListener('pagehide',()=>{stop();finishMic();finishCapture();if(dirty)save()});window.addEventListener('resize',()=>{if(screen==='edit')drawWave()});document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$$('dialog').some(d=>d.open))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)start();return}const i='1234qwerasdfzxcv'.indexOf(e.key.toLowerCase());if(i>=0&&!e.repeat)hit(state.bank*16+i,'typing:'+e.code);if(e.key==='Escape'){stop();stopPreview();audio.apply({filter:0,space:0,echo:0,drive:0});paintFX()}});document.addEventListener('keyup',e=>release('typing:'+e.code));
render();paintFX();boot().catch(e=>{ready=true;render();message('Studio vide : '+e.message)});
